/**
 * Burmese for the Guitar & Bass Companion, keyed by the English text itself.
 *
 * The Companion's explanations are generated by the core engine as English
 * sentences ("E is the 3rd of the C chord."), so besides fixed phrases there are
 * pattern rules that rebuild those sentences in Burmese around the same note and
 * chord names. Anything without a translation is shown in English.
 * Music terms players use as-is (root, 3rd, triad, fill, BPM, tab…) stay in English.
 */

const DEGREE: Record<string, string> = {
  root: "root",
  third: "3rd",
  fifth: "5th",
  "2nd": "2nd",
  "3rd": "3rd",
  "4th": "4th",
  "5th": "5th",
  "7th": "7th",
  "9th": "9th",
  note: "စကေးနုတ်",
  "scale note": "စကေးနုတ်",
};
const deg = (word: string) => DEGREE[word] ?? word;
const and = (list: string) => list.replace(/ and /g, " နဲ့ ");

