type Rule = [RegExp, (...m: string[]) => string];

/** Sentences the engine builds around note and chord names. */
export const RULES_MY: Rule[] = [
  [/^(\S+) is the (root|third|fifth) of the (\S+) chord, so the line lands on a note that belongs to the new chord\.$/,
    (_, n, d, c) => `${n} က ${c} ကော့ဒ်ရဲ့ ${deg(d)} ဖြစ်လို့ လိုင်းက ကော့ဒ်အသစ်ထဲက နုတ်ပေါ် ဆင်းတယ်။`],
  [/^(\S+) is the ([^.]+?) of the (\S+) chord\.$/, (_, n, d, c) => `${n} က ${c} ကော့ဒ်ရဲ့ ${deg(d)} ဖြစ်တယ်။`],
  [/^([A-G][#b]?(?: and [A-G][#b]?)*) connects? toward (\S+)\.$/, (_, list, c) => `${and(list)} က ${c} ဆီ ဆက်ပေးတယ်။`],
  [/^([A-G][#b]?(?: and [A-G][#b]?)*) connects? the chord tones\.$/, (_, list) => `${and(list)} က ကော့ဒ်နုတ်တွေကို ဆက်ပေးတယ်။`],
  [/^Resolve on (\S+), the (root|third|fifth) of the (\S+) chord\.$/, (_, n, d, c) => `${c} ကော့ဒ်ရဲ့ ${deg(d)} ဖြစ်တဲ့ ${n} ပေါ်မှာ ဆုံးပါ။`],
  [/^Quick fill into (\S+)$/, (_, c) => `${c} ဆီ fill မြန်`],
  [/^Short fill into (\S+)$/, (_, c) => `${c} ဆီ fill တို`],
  [/^Each chord change lands on a chord tone of the new chord, and the last note leads back to (\S+)\.$/,
    (_, n) => `ကော့ဒ်ပြောင်းတိုင်း ကော့ဒ်အသစ်ရဲ့ ကော့ဒ်နုတ်ပေါ် ဆင်းပြီး နောက်ဆုံးနုတ်က ${n} ဆီ ပြန်ဦးဆောင်တယ်။`],
  // "E is the 3rd of C; G is the root of G; ..."
  [/^((?:\S+ is the \S+ of \S+(?:; )?)+)\.$/, (_, all) =>
    all.split("; ").map((clause) => clause.replace(/^(\S+) is the (\S+) of (\S+)$/, (_m, n, d, c) => `${n} က ${c} ရဲ့ ${deg(d)}`)).join("၊ ") + "။"],
  [/^([^:.]+): ([^:.]+)\.$/, (_, a, b) => `${PHRASES_MY[a] ?? a}: ${PHRASES_MY[b] ?? b}။`],
  [/^([\w &]+) rhythm leans on this feel\.$/, (_, style) => `${style} rhythm က ဒီခံစားမှုကို အဓိကသုံးတယ်။`],
  [/^([\w &]+) bass$/, (_, style) => `${style} ဘေ့စ်`],
];
